struct app_ctx { const struct config *cfg; struct session *sess; };

/* leaf reads only what it needs */
static int paint_label(struct widget *w, const struct theme *theme);

/* middle layer forwards one context pointer instead of five scalars */
int render_page(struct app_ctx *ctx, struct page *page) {
    for (size_t i = 0; i < page->count; i++)
        if (paint_label(&page->labels[i], ctx->cfg->theme))
            return -1;
    return 0;
}
